import java.io.*;
import java.util.*;

import jakarta.servlet.*;
import jakarta.servlet.annotation.*;
import jakarta.servlet.http.*;
import com.bisangoding.web.*;
import com.fasterxml.jackson.databind.*;

public class Main {
    public static void main(String[] args) {
        ServerUji server = new ServerUji();
        server.konteks().setAttribute("todoService", new TodoService());
        server.tambah(new TodoApiServlet());
        System.out.println(server.kirim("GET", "/api/todo/x").isi());
        System.out.println(server.kirim("GET", "/api/todo/3").isi());
    }
}

class Todo {
    public int id;
    public String judul;
    public boolean selesai;

    public Todo() {
    }

    Todo(int id, String judul) {
        this.id = id;
        this.judul = judul;
    }
}

class TodoTidakDitemukanException extends RuntimeException {
    TodoTidakDitemukanException(int id) {
        super("todo " + id + " tidak ditemukan");
    }
}

class TodoService {
    private final Map<Integer, Todo> data = new TreeMap<>();
    private int idBerikut = 1;

    synchronized Todo tambah(String judul) {
        if (judul == null || judul.trim().isEmpty()) {
            throw new IllegalArgumentException("judul wajib diisi");
        }
        Todo t = new Todo(idBerikut++, judul.trim());
        data.put(t.id, t);
        return t;
    }

    synchronized List<Todo> semua() {
        return new ArrayList<>(data.values());
    }

    synchronized Todo cari(int id) {
        Todo t = data.get(id);
        if (t == null) {
            throw new TodoTidakDitemukanException(id);
        }
        return t;
    }

    synchronized Todo selesaikan(int id) {
        Todo t = cari(id);
        t.selesai = true;
        return t;
    }

    synchronized void hapus(int id) {
        cari(id);
        data.remove(id);
    }
}

@WebServlet("/api/todo/*")
class TodoApiServlet extends HttpServlet {
    private final ObjectMapper json = new ObjectMapper();
    private TodoService service;

    @Override
    public void init() {
        service = (TodoService) getServletContext().getAttribute("todoService");
    }

    @Override
    protected void service(HttpServletRequest req, HttpServletResponse res) throws IOException, ServletException {
        try {
            super.service(req, res);
        } catch (TodoTidakDitemukanException e) {
            kirim(res, 404, Collections.singletonMap("pesan", e.getMessage()));
        } catch (IllegalArgumentException e) {
            kirim(res, 400, Collections.singletonMap("pesan", e.getMessage()));
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse res) throws IOException {
        if (req.getPathInfo() == null) {
            kirim(res, 200, service.semua());
        } else {
            kirim(res, 200, service.cari(nomor(req)));
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse res) throws IOException {
        Todo masuk = json.readValue(req.getReader(), Todo.class);
        Todo t = service.tambah(masuk.judul);
        res.setHeader("Location", "/api/todo/" + t.id);
        kirim(res, 201, t);
    }

    @Override
    protected void doPut(HttpServletRequest req, HttpServletResponse res) throws IOException {
        kirim(res, 200, service.selesaikan(nomor(req)));
    }

    @Override
    protected void doDelete(HttpServletRequest req, HttpServletResponse res) {
        service.hapus(nomor(req));
        res.setStatus(204);
    }

    private int nomor(HttpServletRequest req) {
        try {
            return Integer.parseInt(req.getPathInfo().substring(1));
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("nomor todo harus angka");
        }
    }

    private void kirim(HttpServletResponse res, int status, Object isi) throws IOException {
        res.setStatus(status);
        res.setContentType("application/json;charset=UTF-8");
        json.writeValue(res.getWriter(), isi);
    }
}

